import { eventFacts, activityRange } from './facts.js';
import { uint } from './state.js';
import { compareLogs } from './client.js';

// Payout components are exact chain events. The run portion of a whole-day
// seat is only shown when its settlement is unambiguous; the full verified
// replay supplies ambiguous cases on demand.
export async function readCrapsResults(s,url,{signal}={}) {
  const match=url.pathname.match(/^\/game\/craps\/lobby\/(\d+)\/results$/);if(!match)return undefined;
  const day=uint(match[1]);const {fromBlock}=await activityRange(s,Math.max(1,day-1),signal);
  const slots=Array.from({length:7},(_,i)=>day*8+i+1);if(day>1)slots.unshift((day-1)*8+7);
  const arms=await eventFacts(s,['CrapsBonusArmed'],{contract:'CRAPS',filters:{slot:slots},fromBlock,signal});
  if(!arms.length)return {day,results:[]};
  const keys=arms.map(e=>e.args.battleKey);
  const payouts=await eventFacts(s,['CrapsBattlePaid','CrapsHighRollerPaid','CrapsProgressivePaid'],{contract:'CRAPS',filters:{battleKey:keys},fromBlock,signal});
  const results=[];
  for(const row of payouts.filter(e=>e.name!=='CrapsProgressivePaid')) {
    const a=row.args,slot=BigInt(arms.find(e=>e.args.battleKey===a.battleKey).args.slot);
    const siblings=payouts.filter(e=>e.args.battleKey===a.battleKey&&e.args.betId===a.betId);
    const sum=name=>siblings.filter(e=>e.name===name&&!(name==='CrapsHighRollerPaid'&&e.args.bankrollRider)).reduce((n,e)=>n+BigInt(e.args.paid ?? e.args.amount),0n);
    const battle=sum('CrapsBattlePaid'),high=sum('CrapsHighRollerPaid'),progressive=sum('CrapsProgressivePaid');
    const {contractInterface,decodeLog}=await import('./client.js'); const iface=await contractInterface('CRAPS');
    const receipt=await s.client.receipt(row.transactionHash,signal,row.blockHash);
    const ordered=receipt.logs.filter(e=>e.address.toLowerCase()===s.client.address('CRAPS')).flatMap(e=>{try{const p=decodeLog(iface,e);return p?[{...e,name:p.name,args:p.args}]:[];}catch{return [];}}).sort(compareLogs);
    const settle=ordered.filter(e=>e.name==='CrapsBetSettled'&&String(e.args.betId)===a.betId&&compareLogs(e,row)<0).at(-1);
    // A payout immediately follows this battle's settle walk. Refuse a total
    // if a sibling finalized a different battle between the two events.
    const ambiguous=settle&&ordered.some(e=>e.args.battleKey&&e.args.battleKey!==a.battleKey&&compareLogs(e,settle)>0&&compareLogs(e,row)<0);
    const run=settle&&!ambiguous?BigInt(settle.args.paid):null;
    results.push({day:Number(slot/8n),period:Number(slot%8n)-1,battleKey:a.battleKey,lane:row.name==='CrapsBattlePaid'?'main':'high',betId:a.betId,winner:a.player,
      bankrollRider:row.name==='CrapsHighRollerPaid'?a.bankrollRider:null,runPaidWei:run==null?null:String(run),battlePaidWei:String(battle),highPaidWei:String(high),progressivePaidWei:String(progressive),totalWonWei:run==null?null:String(run+battle+high+progressive),biggestDiceRunHit:null,biggestDiceRunBefore:null});
  }
  return {day,results};
}
